-- Local synthetic fixture only. Never run on hosted data; no provider request is made.
begin;
create temporary table gs(owner_id uuid,outsider uuid,w uuid,s uuid,c uuid,run uuid,profile uuid,test_run uuid,coordinator uuid,content uuid,quality uuid,claim1 uuid,claim2 uuid,claim3 uuid);
insert into gs values(gen_random_uuid(),gen_random_uuid(),null,null,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select owner_id from gs union all select outsider from gs;
create function pg_temp.gsexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;else raise exception 'Unexpected: %',sqlerrm;end if;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on gs to authenticated,anon,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);
update gs set w=(select id from public.bz_create_workspace('Stage accounting fixture'));
update gs set s=(select id from public.bz_register_site(w,'Draft pilot','external','business','https://stage-fixture.com/',null,'active',true));
select public.bz_save_site_agent_preferences(w,s,'{"brandVoice":"practical","audience":"small business owners","guidance":"Draft only"}',0) from gs;
select public.bz_mutate_knowledge(w,s,gen_random_uuid(),'save','{"title":"Approved facts","filename":"facts.md","sourceText":"Bizoveya prepares private reviewable drafts.","facts":[{"id":"f1","text":"Bizoveya prepares private reviewable drafts."}]}',0) from gs;
select public.bz_mutate_knowledge(w,s,(select id from public.bizoveya_knowledge_sources where site_id=s),'approve',null,1) from gs;
select public.bz_save_campaign(w,s,c,'{"title":"Pilot","brief":"Prepare three draft formats","blog":"","pinterest":"","linkedin":""}',0) from gs;
reset role;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile,'stage-fixture',1,1 from gs;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile,1,'{"name":"Fixture Gemini","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic stage fixture' from gs;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile,1,'platform-gemini',1 from gs;
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,input_tokens,output_tokens,reason,finished_at) select test_run,profile,1,'platform-gemini',1,gen_random_uuid(),'passed','response_matched',20,7,'Synthetic connectivity evidence',clock_timestamp() from gs;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile,1,1,jsonb_build_object('enabled',true,'inputRateMicros',0,'outputRateMicros',0,'requestFeeMicros',0,'dailyLimitMicros',10000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/fictional-pricing','reviewed',true),'Synthetic reviewed prices' from gs;
update bizoveya_private.agent_versions set document=jsonb_set(document,'{modelTier}','"economical"') where version=1 and agent_id in(select id from bizoveya_private.agent_definitions where kind in('coordinator','content','quality'));
update bizoveya_private.agent_definitions set preview_version=1 where kind in('coordinator','content','quality');
insert into bizoveya_private.agent_checks(agent_id,version) select id,1 from bizoveya_private.agent_definitions where kind in('coordinator','content','quality') on conflict do nothing;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select a.id,1,g.profile,1,1,g.test_run,1,true,'Synthetic generation binding' from bizoveya_private.agent_definitions a cross join gs g where a.kind in('coordinator','content','quality');
create temporary table rt as select jsonb_build_object('enabled',true,'agents',(select jsonb_agg(jsonb_build_object('kind',kind,'agentId',id,'agentVersion',1) order by kind) from bizoveya_private.agent_definitions)) as document from gs;
grant all on rt to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);

select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',rt.document,'expectedVersion',0,'reason','Enable reviewed site team.','reviewed',true)) from gs,rt;
create temporary table requests(id uuid,campaign uuid,run uuid);insert into requests values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid());grant all on requests to authenticated,service_role;
select public.bz_agency_command(w,s,jsonb_build_object('action','request','id',requests.id,'instruction','Prepare private draft promotion.','channels',jsonb_build_array('blog','linkedin'),'reviewed',true,'inputMode','text')) from gs,requests;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',1,'expectedCampaignVersion',1,'reviewed',true)),'bz_agency_campaign_required') from gs,requests;
select public.bz_handoff_agency_campaign(w,s,jsonb_build_object('id',requests.id,'campaignId',requests.campaign,'expectedVersion',1,'title','Private reviewed task','reviewed',true)) from gs,requests;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',false)),'bz_invalid_agency_generation') from gs,requests;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',1,'expectedCampaignVersion',1,'reviewed',true)),'bz_conflict') from gs,requests;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',2,'reviewed',true)),'bz_conflict') from gs,requests;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',jsonb_set(rt.document,'{enabled}','false'),'expectedVersion',1,'reason','Pause synthetic admission.','reviewed',true)) from gs,rt;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)),'bz_site_roster_paused') from gs,requests;
reset role;
do $$begin if exists(select 1 from bizoveya_private.generation_runs where id=(select run from requests)) or (select version from bizoveya_private.agency_records where id=(select id from requests))<>2 then raise exception 'Rejected preparation changed state';end if;end;$$;
set local role authenticated;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',rt.document,'expectedVersion',2,'reason','Enable synthetic reviewed admission.','reviewed',true)) from gs,rt;
reset role;
update bizoveya_private.agency_records set version=100 where id=(select id from requests);
set local role authenticated;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',100,'expectedCampaignVersion',1,'reviewed',true)),'bz_agency_limit') from gs,requests;
reset role;update bizoveya_private.agency_records set version=2 where id=(select id from requests);
update public.bizoveya_knowledge_sources set approved=false,approved_by=null,approved_at=null where site_id=(select s from gs);
set local role authenticated;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)),'bz_generation_not_ready') from gs,requests;
reset role;update public.bizoveya_knowledge_sources set approved=true,approved_by=(select owner_id from gs),approved_at=clock_timestamp() where site_id=(select s from gs);
set local role authenticated;
select public.bz_prepare_campaign_generation(w,s,c,1,run) from gs;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',gs.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)),'bz_conflict') from gs,requests;
select public.bz_prepare_agency_generation(w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from gs,requests;
select public.bz_prepare_agency_generation(w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from gs,requests;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',gen_random_uuid(),'expectedVersion',3,'expectedCampaignVersion',1,'reviewed',true)),'bz_conflict') from gs,requests;
-- Cancelling the proposal does not authorize cancellation or another run. Exact lost-response retry remains a read.
select public.bz_agency_command(w,s,jsonb_build_object('action','cancel','id',requests.id,'expectedVersion',3,'reason','Cancel proposal only.','reviewed',true)) from gs,requests;
select public.bz_prepare_agency_generation(w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from gs,requests;
reset role;
do $$begin
 if (select count(*) from bizoveya_private.agency_generation_handoffs)<>1 or (select status from bizoveya_private.generation_runs where id=(select run from requests))<>'prepared' or exists(select 1 from bizoveya_private.generation_stage_runs) then raise exception 'Duplicate or executed run';end if;
 if (select input_snapshot->>'siteRosterVersion' from bizoveya_private.generation_runs where id=(select run from requests))<>'3' then raise exception 'Missing exact team version';end if;
 if (select count(*) from bizoveya_private.agency_events where action='prepare-generation')<>1 then raise exception 'Duplicate event';end if;
end;$$;
-- Projection reads current durable status, not the original prepared label.
update bizoveya_private.generation_runs set status='failed',finished_at=clock_timestamp() where id=(select run from requests);
do $$begin if (bizoveya_private.agency_json((select id from requests))#>>'{execution,run,status}')<>'failed' then raise exception 'Stale execution projection';end if;end;$$;
select pg_temp.gsexpect('update bizoveya_private.agency_generation_handoffs set source_version=1','bz_immutable_agency_handoff');
update public.bizoveya_memberships set role='viewer' where user_id=(select owner_id from gs);
set local role authenticated;
select public.bz_agency_inventory(w,s) from gs;
select pg_temp.gsexpect(format('select public.bz_prepare_agency_generation(%L,%L,%L::jsonb)',w,s,jsonb_build_object('id',requests.id,'runId',requests.run,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)),'bz_forbidden') from gs,requests;
select pg_temp.gsexpect('select * from bizoveya_private.agency_generation_handoffs','permission denied');
select set_config('request.jwt.claim.sub',(select outsider::text from gs),true);
select pg_temp.gsexpect(format('select public.bz_agency_inventory(%L,%L)',w,s),'bz_forbidden') from gs;
reset role;
delete from public.bizoveya_sites where id=(select s from gs);
do $$begin if exists(select 1 from bizoveya_private.agency_generation_handoffs) then raise exception 'Missing site cascade';end if;end;$$;
rollback;
